const {chromium}=require('playwright');const fs=require('fs');const path=require('path');
(async()=>{const b=await chromium.launch({executablePath:process.env.CHROMIUM_PATH || '/usr/bin/chromium',args:['--no-sandbox']});const p=await b.newPage();const root=process.cwd();await p.route('https://ev.jworldcreations.com/**',async route=>{const pathname=new URL(route.request().url()).pathname;let file=path.join(root,pathname);try{const body=fs.readFileSync(file);await route.fulfill({body,contentType:file.endsWith('.js')||file.endsWith('.mjs')?'text/javascript':file.endsWith('.html')?'text/html':file.endsWith('.css')?'text/css':file.endsWith('.json')?'application/json':'application/octet-stream'});}catch{await route.fulfill({status:404,body:'Not found'})}});const errors=[];p.on('pageerror',e=>errors.push(e.message));for(const w of [360,768,1440]){await p.setViewportSize({width:w,height:900});await p.goto('https://ev.jworldcreations.com/ev-revival-local.html');await p.waitForFunction(()=>customElements.get('esp-web-install-button'));if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw Error('Overflow');await p.locator('#hardware-confirm').check();if(!await p.locator('#flash-button').isDisabled())throw Error('missing consent gate');await p.locator('#data-loss-confirm').check();if(await p.locator('#flash-button').isDisabled())throw Error('button disabled');await p.selectOption('#install-mode','update');if(!await p.locator('#flash-button').isDisabled())throw Error('update enabled');await p.selectOption('#install-mode','recovery');if(await p.locator('#flash-button').isDisabled())throw Error('recovery disabled');console.log(w,'bundle loaded, consent/update/recovery gates pass');}const result=await p.evaluate(async()=>{const m=await(await fetch('ev-revival-local/manifest.json')).json();const buffers=await window.evRevivalPolicy.prepare({chip:{CHIP_NAME:'ESP32'},getFlashSize:async()=>4096},m,false);return buffers[0].byteLength});console.log('browser Web Crypto verified actual pinned binary:',result);await p.route('**/*.bin',r=>r.fulfill({body:Buffer.alloc(10)}));const error=await p.evaluate(async()=>{try{const m=await(await fetch('ev-revival-local/manifest.json')).json();await window.evRevivalPolicy.prepare({chip:{CHIP_NAME:'ESP32'},getFlashSize:async()=>4096},m,false)}catch(e){return e.message}});if(!error?.includes('wrong size'))throw Error(error);console.log('truncated image stopped:',error);if(errors.length)throw Error(errors.join('\n'));await b.close()})();
